INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-present-continuous','en','present-continuous','正在进行的动作','be + V-ing',1,'正在进行的动作','正在进行的动作','be + V-ing','描述说话时正在做的事；状态动词通常不这样用。','描述说话时正在做的事；状态动词通常不这样用。','描述说话时正在做的事；状态动词通常不这样用。','结合“我正在做晚饭。”理解本用法。','neutral','published',1273);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-present-continuous','en-present-continuous','en','I am cooking dinner.','我正在做晚饭。','描述说话时正在做的事；状态动词通常不这样用。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-do-question','en','do-question','一般现在时问句','Do / Does + subject + verb?',1,'一般现在时问句','一般现在时问句','Do / Does + subject + verb?','询问习惯或喜好；does后动词不加s。','询问习惯或喜好；does后动词不加s。','询问习惯或喜好；does后动词不加s。','结合“你喜欢咖啡吗？”理解本用法。','neutral','published',1274);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-do-question','en-do-question','en','Do you like coffee?','你喜欢咖啡吗？','询问习惯或喜好；does后动词不加s。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-there-is','en','there-is','说明存在','there is / are + noun',1,'说明存在','说明存在','there is / are + noun','首次引入某处存在的人或物；与主语数量一致。','首次引入某处存在的人或物；与主语数量一致。','首次引入某处存在的人或物；与主语数量一致。','结合“附近有一个车站。”理解本用法。','neutral','published',1275);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-there-is','en-there-is','en','There is a station nearby.','附近有一个车站。','首次引入某处存在的人或物；与主语数量一致。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-have-possession','en','have-possession','拥有与身体感受','subject + have / has + noun',1,'拥有与身体感受','拥有与身体感受','subject + have / has + noun','have可以说拥有或不适；不把所有身体状态直接译成have。','have可以说拥有或不适；不把所有身体状态直接译成have。','have可以说拥有或不适；不把所有身体状态直接译成have。','结合“我头疼。”理解本用法。','neutral','published',1276);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-have-possession','en-have-possession','en','I have a headache.','我头疼。','have可以说拥有或不适；不把所有身体状态直接译成have。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-wh-question','en','wh-question','询问信息','wh-word + auxiliary + subject + verb?',1,'询问信息','询问信息','wh-word + auxiliary + subject + verb?','疑问词问特定信息；主语疑问句另有语序。','疑问词问特定信息；主语疑问句另有语序。','疑问词问特定信息；主语疑问句另有语序。','结合“你住在哪里？”理解本用法。','neutral','published',1277);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-wh-question','en-wh-question','en','Where do you live?','你住在哪里？','疑问词问特定信息；主语疑问句另有语序。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-imperative','en','imperative','行动指示','base verb + object',1,'行动指示','行动指示','base verb + object','省略you的指示；please并不消除命令感。','省略you的指示；please并不消除命令感。','省略you的指示；please并不消除命令感。','结合“请等一下。”理解本用法。','neutral','published',1278);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-imperative','en-imperative','en','Wait a moment, please.','请等一下。','省略you的指示；please并不消除命令感。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-want-to','en','want-to','想做某事','want to + base verb',1,'想做某事','想做某事','want to + base verb','表达愿望；want后不能直接接动词原形。','表达愿望；want后不能直接接动词原形。','表达愿望；want后不能直接接动词原形。','结合“我想吃饭。”理解本用法。','neutral','published',1279);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-want-to','en-want-to','en','I want to eat.','我想吃饭。','表达愿望；want后不能直接接动词原形。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-possessive','en','possessive','物品所属','my / your / his / her + noun',1,'物品所属','物品所属','my / your / his / her + noun','限定词后通常接名词，不与冠词重复。','限定词后通常接名词，不与冠词重复。','限定词后通常接名词，不与冠词重复。','结合“这是我的伞。”理解本用法。','neutral','published',1280);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-possessive','en-possessive','en','This is my umbrella.','这是我的伞。','限定词后通常接名词，不与冠词重复。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-can-ability','en','can-ability','能力与许可','can + base verb',2,'能力与许可','能力与许可','can + base verb','本例为能力；请求和许可要看语境。','本例为能力；请求和许可要看语境。','本例为能力；请求和许可要看语境。','结合“我会做饭。”理解本用法。','neutral','published',1281);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-can-ability','en-can-ability','en','I can cook.','我会做饭。','本例为能力；请求和许可要看语境。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-could-request','en','could-request','委婉请求','Could you + base verb?',2,'委婉请求','委婉请求','Could you + base verb?','比直接指令更试探；不一定指过去能力。','比直接指令更试探；不一定指过去能力。','比直接指令更试探；不一定指过去能力。','结合“你能再解释一遍吗？”理解本用法。','neutral','published',1282);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-could-request','en-could-request','en','Could you explain that again?','你能再解释一遍吗？','比直接指令更试探；不一定指过去能力。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-going-to','en','going-to','已有意图','be going to + base verb',2,'已有意图','已有意图','be going to + base verb','表达意图或迹象支持的预测；本例为计划。','表达意图或迹象支持的预测；本例为计划。','表达意图或迹象支持的预测；本例为计划。','结合“我明天打算做饭。”理解本用法。','neutral','published',1283);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-going-to','en-going-to','en','I''m going to cook tomorrow.','我明天打算做饭。','表达意图或迹象支持的预测；本例为计划。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-will','en','will','当场决定与承诺','will + base verb',2,'当场决定与承诺','当场决定与承诺','will + base verb','用于刚作出的决定或承诺；不保证事情必然发生。','用于刚作出的决定或承诺；不保证事情必然发生。','用于刚作出的决定或承诺；不保证事情必然发生。','结合“我会核对你的订单。”理解本用法。','neutral','published',1284);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-will','en-will','en','I''ll check your order.','我会核对你的订单。','用于刚作出的决定或承诺；不保证事情必然发生。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-comparative','en','comparative','比较两者','comparative + than',2,'比较两者','比较两者','comparative + than','短形容词常加er；不要叠用more和er。','短形容词常加er；不要叠用more和er。','短形容词常加er；不要叠用more和er。','结合“这个尺码比那个小。”理解本用法。','neutral','published',1285);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-comparative','en-comparative','en','This size is smaller than that one.','这个尺码比那个小。','短形容词常加er；不要叠用more和er。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-would-like','en','would-like','礼貌愿望与邀请','would like + noun / to-infinitive',2,'礼貌愿望与邀请','礼貌愿望与邀请','would like + noun / to-infinitive','比want语气柔和；like后形式随用途变化。','比want语气柔和；like后形式随用途变化。','比want语气柔和；like后形式随用途变化。','结合“你愿意一起吃午饭吗？”理解本用法。','neutral','published',1286);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-would-like','en-would-like','en','Would you like to have lunch together?','你愿意一起吃午饭吗？','比want语气柔和；like后形式随用途变化。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-let-us','en','let-us','一起行动的建议','Let''s + base verb',2,'一起行动的建议','一起行动的建议','Let''s + base verb','包含说话人在内的建议；不等于允许某人。','包含说话人在内的建议；不等于允许某人。','包含说话人在内的建议；不等于允许某人。','结合“我们明天见吧。”理解本用法。','neutral','published',1287);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-let-us','en-let-us','en','Let''s meet tomorrow.','我们明天见吧。','包含说话人在内的建议；不等于允许某人。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-before-after','en','before-after','动作先后','before / after + clause',2,'动作先后','动作先后','before / after + clause','说时间关系；未来时间从句通常用现在时。','说时间关系；未来时间从句通常用现在时。','说时间关系；未来时间从句通常用现在时。','结合“离开前给我打电话。”理解本用法。','neutral','published',1288);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-before-after','en-before-after','en','Call me before you leave.','离开前给我打电话。','说时间关系；未来时间从句通常用现在时。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-enjoy-ing','en','enjoy-ing','喜欢某项活动','enjoy + V-ing',2,'喜欢某项活动','喜欢某项活动','enjoy + V-ing','enjoy后用动名词，不用to不定式。','enjoy后用动名词，不用to不定式。','enjoy后用动名词，不用to不定式。','结合“我喜欢散步。”理解本用法。','neutral','published',1289);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-enjoy-ing','en-enjoy-ing','en','I enjoy going for walks.','我喜欢散步。','enjoy后用动名词，不用to不定式。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-indirect-question','en','indirect-question','嵌入式疑问','verb + wh-word + subject + verb',3,'嵌入式疑问','嵌入式疑问','verb + wh-word + subject + verb','嵌入部分使用陈述语序；不要保留问句倒装。','嵌入部分使用陈述语序；不要保留问句倒装。','嵌入部分使用陈述语序；不要保留问句倒装。','结合“我不知道车站在哪里。”理解本用法。','neutral','published',1290);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-indirect-question','en-indirect-question','en','I don''t know where the station is.','我不知道车站在哪里。','嵌入部分使用陈述语序；不要保留问句倒装。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-let-object','en','let-object','让某人做','let + object + base verb',3,'让某人做','让某人做','let + object + base verb','let后省略to；本例请求机会确认理解。','let后省略to；本例请求机会确认理解。','let后省略to；本例请求机会确认理解。','结合“让我确认自己理解正确。”理解本用法。','neutral','published',1291);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-let-object','en-let-object','en','Let me make sure I understand.','让我确认自己理解正确。','let后省略to；本例请求机会确认理解。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-present-perfect-continuous','en','present-perfect-continuous','持续到现在的动作','have / has been + V-ing',4,'持续到现在的动作','持续到现在的动作','have / has been + V-ing','强调持续过程；与现在完成时的结果视角不同。','强调持续过程；与现在完成时的结果视角不同。','强调持续过程；与现在完成时的结果视角不同。','结合“水龙头滴了一整夜。”理解本用法。','neutral','published',1292);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-present-perfect-continuous','en-present-perfect-continuous','en','The faucet has been dripping all night.','水龙头滴了一整夜。','强调持续过程；与现在完成时的结果视角不同。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-since-for','en','since-for','持续的起点与时长','present perfect + since / for',3,'持续的起点与时长','持续的起点与时长','present perfect + since / for','since接起点，for接时长；不要混用。','since接起点，for接时长；不要混用。','since接起点，for接时长；不要混用。','结合“我从周一开始头疼。”理解本用法。','neutral','published',1293);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-since-for','en-since-for','en','I''ve had a headache since Monday.','我从周一开始头疼。','since接起点，for接时长；不要混用。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-as-long-as','en','as-long-as','只要这个条件成立','as long as + clause',3,'只要这个条件成立','只要这个条件成立','as long as + clause','此处是充分条件，不是持续时间。','此处是充分条件，不是持续时间。','此处是充分条件，不是持续时间。','结合“只要早点开始，我们今天就能完成。”理解本用法。','neutral','published',1294);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-as-long-as','en-as-long-as','en','As long as we start early, we can finish today.','只要早点开始，我们今天就能完成。','此处是充分条件，不是持续时间。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-would-rather','en','would-rather','偏好某种行动','would rather + base verb',3,'偏好某种行动','偏好某种行动','would rather + base verb','本例同一主语，rather后不加to。','本例同一主语，rather后不加to。','本例同一主语，rather后不加to。','结合“我更想要不那么甜的东西。”理解本用法。','neutral','published',1295);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-would-rather','en-would-rather','en','I''d rather have something less sweet.','我更想要不那么甜的东西。','本例同一主语，rather后不加to。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-remember-to','en','remember-to','记得去做','remember to + verb',3,'记得去做','记得去做','remember to + verb','指尚待执行的事；remember doing是记得做过。','指尚待执行的事；remember doing是记得做过。','指尚待执行的事；remember doing是记得做过。','结合“离开前记得锁门。”理解本用法。','neutral','published',1296);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-remember-to','en-remember-to','en','Remember to lock the door before you leave.','离开前记得锁门。','指尚待执行的事；remember doing是记得做过。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-between-and','en','between-and','在两项之间选择','between A and B',2,'在两项之间选择','在两项之间选择','between A and B','两项结构应平行；不是between A to B。','两项结构应平行；不是between A to B。','两项结构应平行；不是between A to B。','结合“我正在蓝色和黑色之间选择。”理解本用法。','neutral','published',1297);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-between-and','en-between-and','en','I''m choosing between the blue one and the black one.','我正在蓝色和黑色之间选择。','两项结构应平行；不是between A to B。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-what-if','en','what-if','提出假设问题','What if + clause?',3,'提出假设问题','提出假设问题','What if + clause?','询问假设后果；需要上下文说明关心什么。','询问假设后果；需要上下文说明关心什么。','询问假设后果；需要上下文说明关心什么。','结合“如果不合身怎么办？”理解本用法。','neutral','published',1298);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-what-if','en-what-if','en','What if it doesn''t fit?','如果不合身怎么办？','询问假设后果；需要上下文说明关心什么。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-take-time','en','take-time','需要多长时间','It takes + time + to-infinitive',2,'需要多长时间','需要多长时间','It takes + time + to-infinitive','it是形式主语；真正的活动由不定式说明。','it是形式主语；真正的活动由不定式说明。','it是形式主语；真正的活动由不定式说明。','结合“到那里要二十分钟。”理解本用法。','neutral','published',1299);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-take-time','en-take-time','en','It takes twenty minutes to get there.','到那里要二十分钟。','it是形式主语；真正的活动由不定式说明。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-even-if','en','even-if','即使某条件成立','even if + clause',4,'即使某条件成立','即使某条件成立','even if + clause','提出假设让步；even though通常接已知事实。','提出假设让步；even though通常接已知事实。','提出假设让步；even though通常接已知事实。','结合“即使绕路，也还是更快。”理解本用法。','neutral','published',1300);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-even-if','en-even-if','en','Even if we take a detour, it''s still faster.','即使绕路，也还是更快。','提出假设让步；even though通常接已知事实。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-look-like','en','look-like','根据迹象推测','It looks like + clause',3,'根据迹象推测','根据迹象推测','It looks like + clause','like后此处是完整从句；表达判断而非确定事实。','like后此处是完整从句；表达判断而非确定事实。','like后此处是完整从句；表达判断而非确定事实。','结合“看起来要下雨了。”理解本用法。','neutral','published',1301);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-look-like','en-look-like','en','It looks like it''s going to rain.','看起来要下雨了。','like后此处是完整从句；表达判断而非确定事实。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-regardless','en','regardless','不受条件影响','regardless of + noun / wh-clause',5,'不受条件影响','不受条件影响','regardless of + noun / wh-clause','of是介词；语气较正式，强调条件不改变决定。','of是介词；语气较正式，强调条件不改变决定。','of是介词；语气较正式，强调条件不改变决定。','结合“不管预报如何，我们都应该有备用方案。”理解本用法。','formal','published',1302);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-regardless','en-regardless','en','Regardless of the forecast, we should have a backup plan.','不管预报如何，我们都应该有备用方案。','of是介词；语气较正式，强调条件不改变决定。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-make-feel','en','make-feel','使某人产生感受','make + object + feel + adjective',3,'使某人产生感受','使某人产生感受','make + object + feel + adjective','主动语态make后动词不加to。','主动语态make后动词不加to。','主动语态make后动词不加to。','结合“这让我感到平静。”理解本用法。','neutral','published',1303);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-make-feel','en-make-feel','en','It makes me feel calm.','这让我感到平静。','主动语态make后动词不加to。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-not-quite','en','not-quite','尚未完全达到','not quite + adjective',3,'尚未完全达到','尚未完全达到','not quite + adjective','是程度保留，不是彻底否定。','是程度保留，不是彻底否定。','是程度保留，不是彻底否定。','结合“我还没完全好，但好些了。”理解本用法。','neutral','published',1304);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-not-quite','en-not-quite','en','I''m not quite well, but I''m better.','我还没完全好，但好些了。','是程度保留，不是彻底否定。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-worried-that','en','worried-that','说明担忧内容','be worried + (that) clause',3,'说明担忧内容','说明担忧内容','be worried + (that) clause','表达担心的内容；与worry about名词结构区分。','表达担心的内容；与worry about名词结构区分。','表达担心的内容；与worry about名词结构区分。','结合“我本来担心会迟到，但我们准时到了。”理解本用法。','neutral','published',1305);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-worried-that','en-worried-that','en','I was worried we''d be late, but we arrived on time.','我本来担心会迟到，但我们准时到了。','表达担心的内容；与worry about名词结构区分。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-start-ing','en','start-ing','开始活动','start + V-ing / to-infinitive',3,'开始活动','开始活动','start + V-ing / to-infinitive','本例强调最近开始的新活动，两种形式常可互换。','本例强调最近开始的新活动，两种形式常可互换。','本例强调最近开始的新活动，两种形式常可互换。','结合“我开始学吉他了。”理解本用法。','neutral','published',1306);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-start-ing','en-start-ing','en','I''ve started learning guitar.','我开始学吉他了。','本例强调最近开始的新活动，两种形式常可互换。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-the-more','en','the-more','程度随之变化','the + comparative ..., the + comparative ...',5,'程度随之变化','程度随之变化','the + comparative ..., the + comparative ...','两个比较结构相互关联；不是最高级。','两个比较结构相互关联；不是最高级。','两个比较结构相互关联；不是最高级。','结合“我越练习就越享受。”理解本用法。','formal','published',1307);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-the-more','en-the-more','en','The more I practise, the more I enjoy it.','我越练习就越享受。','两个比较结构相互关联；不是最高级。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-sooner-better','en','sooner-better','越早越好','The sooner + clause, the better',4,'越早越好','越早越好','The sooner + clause, the better','固定比较关联结构；不能写成the soon。','固定比较关联结构；不能写成the soon。','固定比较关联结构；不能写成the soon。','结合“我们越早预订越好。”理解本用法。','neutral','published',1308);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-sooner-better','en-sooner-better','en','The sooner we book, the better.','我们越早预订越好。','固定比较关联结构；不能写成the soon。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-if-request','en','if-request','先确认条件再请求','If + present clause, could you ...?',3,'先确认条件再请求','先确认条件再请求','If + present clause, could you ...?','给对方选择余地；could不是过去时间标志。','给对方选择余地；could不是过去时间标志。','给对方选择余地；could不是过去时间标志。','结合“如果你有空，能检查一下这个吗？”理解本用法。','neutral','published',1309);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-if-request','en-if-request','en','If you have a moment, could you check this?','如果你有空，能检查一下这个吗？','给对方选择余地；could不是过去时间标志。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-mind-ing','en','mind-ing','询问是否介意','Would you mind + V-ing?',4,'询问是否介意','询问是否介意','Would you mind + V-ing?','mind后接动名词；否定回答常表示不介意。','mind后接动名词；否定回答常表示不介意。','mind后接动名词；否定回答常表示不介意。','结合“你介意开一下窗吗？”理解本用法。','neutral','published',1310);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-mind-ing','en-mind-ing','en','Would you mind opening the window?','你介意开一下窗吗？','mind后接动名词；否定回答常表示不介意。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-ever-perfect','en','ever-perfect','到现在的经历','Have you ever + past participle?',3,'到现在的经历','到现在的经历','Have you ever + past participle?','不指定已结束的具体时间；过去分词与过去式可能不同。','不指定已结束的具体时间；过去分词与过去式可能不同。','不指定已结束的具体时间；过去分词与过去式可能不同。','结合“你去过京都吗？”理解本用法。','neutral','published',1311);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-ever-perfect','en-ever-perfect','en','Have you ever been to Kyoto?','你去过京都吗？','不指定已结束的具体时间；过去分词与过去式可能不同。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-not-that','en','not-that','否定某种推断','It''s not that + clause',5,'否定某种推断','否定某种推断','It''s not that + clause','否定解释而不否定所有相关事实；通常需补充真正原因。','否定解释而不否定所有相关事实；通常需补充真正原因。','否定解释而不否定所有相关事实；通常需补充真正原因。','结合“并不是我想争论。”理解本用法。','formal','published',1312);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-not-that','en-not-that','en','It''s not that I want to argue.','并不是我想争论。','否定解释而不否定所有相关事实；通常需补充真正原因。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-about-time','en','about-time','早该做某事','It''s about time + subject + past form',5,'早该做某事','早该做某事','It''s about time + subject + past form','过去形式表达当前早该做的事，常含不满。','过去形式表达当前早该做的事，常含不满。','过去形式表达当前早该做的事，常含不满。','结合“我们早该打扫厨房了。”理解本用法。','formal','published',1313);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-about-time','en-about-time','en','It''s about time we cleaned the kitchen.','我们早该打扫厨房了。','过去形式表达当前早该做的事，常含不满。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-would-have','en','would-have','未实现的过去结果','would have + past participle',5,'未实现的过去结果','未实现的过去结果','would have + past participle','需要明确未实现条件或阻碍；不等同于单纯过去打算。','需要明确未实现条件或阻碍；不等同于单纯过去打算。','需要明确未实现条件或阻碍；不等同于单纯过去打算。','结合“我本来会去，但不得不工作。”理解本用法。','formal','published',1314);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-would-have','en-would-have','en','I would have gone, but I had to work.','我本来会去，但不得不工作。','需要明确未实现条件或阻碍；不等同于单纯过去打算。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-should-have','en','should-have','回顾过去的更好选择','should have + past participle',4,'回顾过去的更好选择','回顾过去的更好选择','should have + past participle','常表达后悔或批评；不能用should had。','常表达后悔或批评；不能用should had。','常表达后悔或批评；不能用should had。','结合“我当时应该等一等。”理解本用法。','neutral','published',1315);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-should-have','en-should-have','en','I should have waited.','我当时应该等一等。','常表达后悔或批评；不能用should had。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-relative-clause','en','relative-clause','限定名词范围','noun + who / that / which + clause',4,'限定名词范围','限定名词范围','noun + who / that / which + clause','限定从句识别所指对象；本例不用逗号隔开。','限定从句识别所指对象；本例不用逗号隔开。','限定从句识别所指对象；本例不用逗号隔开。','结合“你借给我的那本书很有用。”理解本用法。','neutral','published',1316);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-relative-clause','en-relative-clause','en','The book that you lent me was useful.','你借给我的那本书很有用。','限定从句识别所指对象；本例不用逗号隔开。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-passive','en','passive','以承受者为主语','be + past participle',3,'以承受者为主语','以承受者为主语','be + past participle','焦点放在动作承受者；by短语可以省略。','焦点放在动作承受者；by短语可以省略。','焦点放在动作承受者；by短语可以省略。','结合“列车被取消了。”理解本用法。','neutral','published',1317);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-passive','en-passive','en','The train was cancelled.','列车被取消了。','焦点放在动作承受者；by短语可以省略。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-second-conditional','en','second-conditional','假设现在的不同情况','If + past, would + base verb',4,'假设现在的不同情况','假设现在的不同情况','If + past, would + base verb','过去形式标示距离现实，不自动是过去时间。','过去形式标示距离现实，不自动是过去时间。','过去形式标示距离现实，不自动是过去时间。','结合“如果有更多时间，我会学日语。”理解本用法。','neutral','published',1318);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-second-conditional','en-second-conditional','en','If I had more time, I would learn Japanese.','如果有更多时间，我会学日语。','过去形式标示距离现实，不自动是过去时间。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-third-conditional','en','third-conditional','假设不同的过去','If + past perfect, would have + participle',5,'假设不同的过去','假设不同的过去','If + past perfect, would have + participle','反事实地回看过去条件及结果；不要在if从句机械加would。','反事实地回看过去条件及结果；不要在if从句机械加would。','反事实地回看过去条件及结果；不要在if从句机械加would。','结合“如果早些出发，我就赶上车了。”理解本用法。','formal','published',1319);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-third-conditional','en-third-conditional','en','If I had left earlier, I would have caught the train.','如果早些出发，我就赶上车了。','反事实地回看过去条件及结果；不要在if从句机械加would。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-concessive-although','en','concessive-although','承认事实再转折','although + clause, main clause',4,'承认事实再转折','承认事实再转折','although + clause, main clause','although和but通常不在同一对应位置叠用。','although和but通常不在同一对应位置叠用。','although和but通常不在同一对应位置叠用。','结合“虽然贵，但它很有用。”理解本用法。','neutral','published',1320);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-concessive-although','en-concessive-although','en','Although it was expensive, it was useful.','虽然贵，但它很有用。','although和but通常不在同一对应位置叠用。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-hedged-claim','en','hedged-claim','谨慎提出论断','evidence suggests that + clause',5,'谨慎提出论断','谨慎提出论断','evidence suggests that + clause','证据支持推断并不等于证明因果；明确主张范围。','证据支持推断并不等于证明因果；明确主张范围。','证据支持推断并不等于证明因果；明确主张范围。','结合“证据表明这种方法可能有效。”理解本用法。','formal','published',1321);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-hedged-claim','en-hedged-claim','en','The evidence suggests that the approach is effective.','证据表明这种方法可能有效。','证据支持推断并不等于证明因果；明确主张范围。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-inversion','en','inversion','否定副词前置倒装','Rarely + auxiliary + subject + verb',6,'否定副词前置倒装','否定副词前置倒装','Rarely + auxiliary + subject + verb','正式强调，助动词置于主语前；普通陈述不必倒装。','正式强调，助动词置于主语前；普通陈述不必倒装。','正式强调，助动词置于主语前；普通陈述不必倒装。','结合“我们很少看到如此清晰的结果。”理解本用法。','formal','published',1322);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-inversion','en-inversion','en','Rarely do we see such a clear result.','我们很少看到如此清晰的结果。','正式强调，助动词置于主语前；普通陈述不必倒装。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-participle-clause','en','participle-clause','分词补充背景','Having + past participle, main clause',6,'分词补充背景','分词补充背景','Having + past participle, main clause','分词隐含主语应与主句一致，避免悬垂分词。','分词隐含主语应与主句一致，避免悬垂分词。','分词隐含主语应与主句一致，避免悬垂分词。','结合“核对数字后，我们修改了报告。”理解本用法。','formal','published',1323);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-participle-clause','en-participle-clause','en','Having checked the figures, we revised the report.','核对数字后，我们修改了报告。','分词隐含主语应与主句一致，避免悬垂分词。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-cleft','en','cleft','强调特定信息','It is / was X that ...',6,'强调特定信息','强调特定信息','It is / was X that ...','用强调结构聚焦信息；不是一般关系从句的简单替换。','用强调结构聚焦信息；不是一般关系从句的简单替换。','用强调结构聚焦信息；不是一般关系从句的简单替换。','结合“正是费用让我改变了想法。”理解本用法。','formal','published',1324);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-cleft','en-cleft','en','It was the cost that changed my mind.','正是费用让我改变了想法。','用强调结构聚焦信息；不是一般关系从句的简单替换。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-qualified-comparison','en','qualified-comparison','限制比较结论','more ... in terms of X, but ...',6,'限制比较结论','限制比较结论','more ... in terms of X, but ...','明确比较维度，避免把局部优势说成全面优势。','明确比较维度，避免把局部优势说成全面优势。','明确比较维度，避免把局部优势说成全面优势。','结合“这个选项更省时间，但灵活性较低。”理解本用法。','formal','published',1325);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-qualified-comparison','en-qualified-comparison','en','This option is more efficient in terms of time, but less flexible.','这个选项更省时间，但灵活性较低。','明确比较维度，避免把局部优势说成全面优势。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-mixed-conditional','en','mixed-conditional','过去条件影响现在','If + past perfect, would + base verb',6,'过去条件影响现在','过去条件影响现在','If + past perfect, would + base verb','过去未实现条件带来现在的假设结果；两部分时间不同。','过去未实现条件带来现在的假设结果；两部分时间不同。','过去未实现条件带来现在的假设结果；两部分时间不同。','结合“如果当时接受邀约，我现在就住在国外了。”理解本用法。','formal','published',1326);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-mixed-conditional','en-mixed-conditional','en','If I had accepted the offer, I would live abroad now.','如果当时接受邀约，我现在就住在国外了。','过去未实现条件带来现在的假设结果；两部分时间不同。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-greeting','en','greeting','程式化社交回应','greeting / thanks formula',1,'程式化社交回应','程式化社交回应','greeting / thanks formula','完整社交行为可用固定短语完成；需看问候、感谢或祝愿语境。','完整社交行为可用固定短语完成；需看问候、感谢或祝愿语境。','完整社交行为可用固定短语完成；需看问候、感谢或祝愿语境。','结合“非常感谢。”理解本用法。','neutral','published',1327);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-greeting','en-greeting','en','Thanks a lot.','非常感谢。','完整社交行为可用固定短语完成；需看问候、感谢或祝愿语境。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-noun-please','en','noun-please','简短礼貌回应','noun / short response + please / thanks',1,'简短礼貌回应','简短礼貌回应','noun / short response + please / thanks','语境补足省略信息；please用于请求，thanks用于感谢。','语境补足省略信息；please用于请求，thanks用于感谢。','语境补足省略信息；please用于请求，thanks用于感谢。','结合“请给我水。”理解本用法。','neutral','published',1328);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-noun-please','en-noun-please','en','Water, please.','请给我水。','语境补足省略信息；please用于请求，thanks用于感谢。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-possible-request','en','possible-request','询问请求是否可行','Would it be possible to + verb?',4,'询问请求是否可行','询问请求是否可行','Would it be possible to + verb?','试探可行性以减弱强迫；不是假装对方必须同意。','试探可行性以减弱强迫；不是假装对方必须同意。','试探可行性以减弱强迫；不是假装对方必须同意。','结合“能换一下这个吗？”理解本用法。','neutral','published',1329);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-en-possible-request','en-possible-request','en','Would it be possible to change this?','能换一下这个吗？','试探可行性以减弱强迫；不是假装对方必须同意。','[]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-shall-suggestion','en','shall-suggestion','共同提议问句','Shall we + base verb?',2,'共同提议问句','共同提议问句','Shall we + base verb?','提出共同方案；不表示预测未来。','提出共同方案；不表示预测未来。','提出共同方案；不表示预测未来。','结合“我们六点在外面见好吗？”理解本用法。','neutral','published',1330);
