INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-seem-to','en','seem-to','保留判断','seem to + base verb',4,'保留判断','保留判断','seem to + base verb','表示表象推断而非直接保证；可接进行或完成形式。','表示表象推断而非直接保证；可接进行或完成形式。','表示表象推断而非直接保证；可接进行或完成形式。','结合“好像开始放晴了。”理解本用法。','neutral','published',1331);
