INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-could-use','en','could-use','委婉表示需要','could use + noun',3,'委婉表示需要','委婉表示需要','could use + noun','表达此刻很需要，不是过去能使用。','表达此刻很需要，不是过去能使用。','表达此刻很需要，不是过去能使用。','结合“我很想短暂休息一下。”理解本用法。','neutral','published',1332);
