INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-not-have-to','en','not-have-to','没有必要','do not have to + verb',3,'没有必要','没有必要','do not have to + verb','不是禁止；must not才常表示禁止。','不是禁止；must not才常表示禁止。','不是禁止；must not才常表示禁止。','结合“你不必说。”理解本用法。','neutral','published',1333);
