INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-help-infinitive','en','help-infinitive','帮助实现','help + object + (to) verb',3,'帮助实现','帮助实现','help + object + (to) verb','help后to可省略；不要误写为help someone doing。','help后to可省略；不要误写为help someone doing。','help后to可省略；不要误写为help someone doing。','结合“这有助于我放松。”理解本用法。','neutral','published',1334);
