INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('en-ellipsis','en','ellipsis','语境中的省略回应','short answer with recoverable content',2,'语境中的省略回应','语境中的省略回应','short answer with recoverable content','上下文必须让省略的信息清楚；不能独立推断所有含义。','上下文必须让省略的信息清楚；不能独立推断所有含义。','上下文必须让省略的信息清楚；不能独立推断所有含义。','结合“还没有，但我想去。”理解本用法。','neutral','published',1335);
