INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-de-place','ja','de-place','动作场所','场所 + で + 动词',1,'动作场所','动作场所','场所 + で + 动词','说明动作在哪里发生；存在位置常用に。','说明动作在哪里发生；存在位置常用に。','说明动作在哪里发生；存在位置常用に。','结合“在家吃饭。”理解本用法。','neutral','published',1340);
