INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-no-possession','ja','no-possession','所属与修饰','名词 + の + 名词',1,'所属与修饰','所属与修饰','名词 + の + 名词','前项限制后项；不意味着只能表示所有权。','前项限制后项；不意味着只能表示所有权。','前项限制后项；不意味着只能表示所有权。','结合“是我的伞。”理解本用法。','neutral','published',1341);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-no-possession','ja-no-possession','ja','私の傘です。','是我的伞。','前项限制后项；不意味着只能表示所有权。','[{"text":"私","reading":"わたし"},{"text":"の"},{"text":"傘","reading":"かさ"},{"text":"です。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-ka-question','ja','ka-question','礼貌疑问','礼貌句 + か',1,'礼貌疑问','礼貌疑问','礼貌句 + か','句末か构成问句，口语语调也有作用。','句末か构成问句，口语语调也有作用。','句末か构成问句，口语语调也有作用。','结合“车站在哪里？”理解本用法。','neutral','published',1342);
