INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-i-adjective','ja','i-adjective','い形容词陈述','い形容词 + です',1,'い形容词陈述','い形容词陈述','い形容词 + です','い形容词可直接修饰名词；不要加な。','い形容词可直接修饰名词；不要加な。','い形容词可直接修饰名词；不要加な。','结合“这个很辣。”理解本用法。','neutral','published',1343);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-i-adjective','ja-i-adjective','ja','これは辛いです。','这个很辣。','い形容词可直接修饰名词；不要加な。','[{"text":"これは"},{"text":"辛","reading":"から"},{"text":"いです。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-suki','ja','suki','表达喜好','名词 + が / は好きです',1,'表达喜好','表达喜好','名词 + が / は好きです','好き是な形容词，不按英语like的动词结构处理。','好き是な形容词，不按英语like的动词结构处理。','好き是な形容词，不按英语like的动词结构处理。','结合“你喜欢咖啡吗？”理解本用法。','neutral','published',1344);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-suki','ja-suki','ja','コーヒーは好きですか。','你喜欢咖啡吗？','好き是な形容词，不按英语like的动词结构处理。','[{"text":"コーヒーは","reading":"こーひーは"},{"text":"好","reading":"す"},{"text":"きですか。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-tai','ja','tai','自己的愿望','ます干 + たい',2,'自己的愿望','自己的愿望','ます干 + たい','表达说话人的愿望；第三者的内心愿望需要证据或转述。','表达说话人的愿望；第三者的内心愿望需要证据或转述。','表达说话人的愿望；第三者的内心愿望需要证据或转述。','结合“你想吃什么？”理解本用法。','neutral','published',1345);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-tai','ja-tai','ja','何が食べたいですか。','你想吃什么？','表达说话人的愿望；第三者的内心愿望需要证据或转述。','[{"text":"何","reading":"なに"},{"text":"が"},{"text":"食","reading":"た"},{"text":"べたいですか。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-nai','ja','nai','普通体否定','动词ない形',2,'普通体否定','普通体否定','动词ない形','按动词类别变形；わかる变わからない。','按动词类别变形；わかる变わからない。','按动词类别变形；わかる变わからない。','结合“我不知道。”理解本用法。','neutral','published',1346);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-nai','ja-nai','ja','わからない。','我不知道。','按动词类别变形；わかる变わからない。','[{"text":"わからない。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-potential','ja','potential','能够做到','可能形',2,'能够做到','能够做到','可能形','食べる→食べられる，行く→行ける；不要与被动机械混同。','食べる→食べられる，行く→行ける；不要与被动机械混同。','食べる→食べられる，行く→行ける；不要与被动机械混同。','结合“我不能吃花生。”理解本用法。','neutral','published',1347);
