INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-te-mo-ii','ja','te-mo-ii','许可','て形 + もいい',2,'许可','许可','て形 + もいい','询问是否允许；不是陈述已有能力。','询问是否允许；不是陈述已有能力。','询问是否允许；不是陈述已有能力。','结合“可以试穿吗？”理解本用法。','neutral','published',1348);
