INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-mashou','ja','mashou','共同提议','ます干 + ましょう',2,'共同提议','共同提议','ます干 + ましょう','邀请或提议共同做，语气较明确。','邀请或提议共同做，语气较明确。','邀请或提议共同做，语气较明确。','结合“下次一起散步吧。”理解本用法。','neutral','published',1349);
