INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-masen-ka','ja','masen-ka','邀请','ます干 + ませんか',2,'邀请','邀请','ます干 + ませんか','形式是否定问句，功能可为邀请。','形式是否定问句，功能可为邀请。','形式是否定问句，功能可为邀请。','结合“一起吃午饭好吗？”理解本用法。','neutral','published',1350);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-masen-ka','ja-masen-ka','ja','一緒にお昼を食べませんか。','一起吃午饭好吗？','形式是否定问句，功能可为邀请。','[{"text":"一緒","reading":"いっしょ"},{"text":"にお"},{"text":"昼","reading":"ひる"},{"text":"を"},{"text":"食","reading":"た"},{"text":"べませんか。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-mae-ni','ja','mae-ni','动作之前','辞书形 + 前に',2,'动作之前','动作之前','辞书形 + 前に','前接辞书形，即使整个句子说过去。','前接辞书形，即使整个句子说过去。','前接辞书形，即使整个句子说过去。','结合“出门前确认钥匙。”理解本用法。','neutral','published',1351);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-mae-ni','ja-mae-ni','ja','出かける前に、鍵を確認します。','出门前确认钥匙。','前接辞书形，即使整个句子说过去。','[{"text":"出","reading":"で"},{"text":"かける"},{"text":"前","reading":"まえ"},{"text":"に、"},{"text":"鍵","reading":"かぎ"},{"text":"を"},{"text":"確認","reading":"かくにん"},{"text":"します。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-kara-after','ja','kara-after','完成后再做','て形 + から',2,'完成后再做','完成后再做','て形 + から','突出先完成前项再做后项。','突出先完成前项再做后项。','突出先完成前项再做后项。','结合“吃完再去。”理解本用法。','neutral','published',1352);
