INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-hou-ga-ii','ja','hou-ga-ii','建议','た形 / ない形 + ほうがいい',3,'建议','建议','た形 / ない形 + ほうがいい','肯定建议常用た形；对上级可能显得直接。','肯定建议常用た形；对上级可能显得直接。','肯定建议常用た形；对上级可能显得直接。','结合“差不多该打扫厨房了。”理解本用法。','neutral','published',1353);
