INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-nara','ja','nara','承接条件','普通形 + なら',3,'承接条件','承接条件','普通形 + なら','根据对方信息或假设提出判断；时序不等同于たら。','根据对方信息或假设提出判断；时序不等同于たら。','根据对方信息或假设提出判断；时序不等同于たら。','结合“如果早点开始，今天能完成。”理解本用法。','neutral','published',1356);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-nara','ja-nara','ja','早めに始めるなら、今日中に終えられます。','如果早点开始，今天能完成。','根据对方信息或假设提出判断；时序不等同于たら。','[{"text":"早","reading":"はや"},{"text":"めに"},{"text":"始","reading":"はじ"},{"text":"めるなら、"},{"text":"今日中","reading":"きょうじゅう"},{"text":"に"},{"text":"終","reading":"お"},{"text":"えられます。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-tara','ja','tara','条件或完成后','た形 + ら',3,'条件或完成后','条件或完成后','た形 + ら','本例假设不合身的后果；也能说前项完成后的事件。','本例假设不合身的后果；也能说前项完成后的事件。','本例假设不合身的后果；也能说前项完成后的事件。','结合“如果尺码不合适怎么办？”理解本用法。','neutral','published',1357);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-tara','ja-tara','ja','もしサイズが合わなかったら、どうなりますか。','如果尺码不合适怎么办？','本例假设不合身的后果；也能说前项完成后的事件。','[{"text":"もしサイズが","reading":"もしさいずが"},{"text":"合","reading":"あ"},{"text":"わなかったら、どうなりますか。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-temo','ja','temo','让步','て形 + も',3,'让步','让步','て形 + も','即使前项成立，后项仍成立；たとえ加强假设。','即使前项成立，后项仍成立；たとえ加强假设。','即使前项成立，后项仍成立；たとえ加强假设。','结合“即使绕路，这边也更快。”理解本用法。','neutral','published',1358);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-temo','ja-temo','ja','たとえ回り道をしても、こちらのほうが早いです。','即使绕路，这边也更快。','即使前项成立，后项仍成立；たとえ加强假设。','[{"text":"たとえ"},{"text":"回","reading":"まわ"},{"text":"り"},{"text":"道","reading":"みち"},{"text":"をしても、こちらのほうが"},{"text":"早","reading":"はや"},{"text":"いです。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-ba-hodo','ja','ba-hodo','程度关联','ば形 + 同一词辞书形 + ほど',5,'程度关联','程度关联','ば形 + 同一词辞书形 + ほど','表示程度联动；不是普通的条件结果。','表示程度联动；不是普通的条件结果。','表示程度联动；不是普通的条件结果。','结合“越练习越有趣。”理解本用法。','formal','published',1359);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-ba-hodo','ja-ba-hodo','ja','練習すればするほど、楽しくなります。','越练习越有趣。','表示程度联动；不是普通的条件结果。','[{"text":"練習","reading":"れんしゅう"},{"text":"すればするほど、"},{"text":"楽","reading":"たの"},{"text":"しくなります。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-wake-dewa-nai','ja','wake-dewa-nai','否定推断','普通形 + わけではない',4,'否定推断','否定推断','普通形 + わけではない','否定由上下文产生的结论；并非简单事实否定。','否定由上下文产生的结论；并非简单事实否定。','否定由上下文产生的结论；并非简单事实否定。','结合“并不是我想争论。”理解本用法。','neutral','published',1360);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-wake-dewa-nai','ja-wake-dewa-nai','ja','言い争いたいわけではありません。','并不是我想争论。','否定由上下文产生的结论；并非简单事实否定。','[{"text":"言","reading":"い"},{"text":"い"},{"text":"争","reading":"あらそ"},{"text":"いたいわけではありません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-koto-ga-aru','ja','koto-ga-aru','过去经历','た形 + ことがある',3,'过去经历','过去经历','た形 + ことがある','把一次或多次经历作为经验；不是一般过去叙述。','把一次或多次经历作为经验；不是一般过去叙述。','把一次或多次经历作为经验；不是一般过去叙述。','结合“你去过京都吗？”理解本用法。','neutral','published',1361);
