INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-hajimeru','ja','hajimeru','开始一个动作','ます干 + 始める',3,'开始一个动作','开始一个动作','ます干 + 始める','复合动词表示动作开始；区分自动词始まる。','复合动词表示动作开始；区分自动词始まる。','复合动词表示动作开始；区分自动词始まる。','结合“最近开始学吉他了。”理解本用法。','neutral','published',1362);
