INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-to-condition','ja','to-condition','自然结果','普通形 + と',3,'自然结果','自然结果','普通形 + と','常说习惯或自然结果；后项一般不直接用意志请求。','常说习惯或自然结果；后项一般不直接用意志请求。','常说习惯或自然结果；后项一般不直接用意志请求。','结合“听这首曲子就感到平静。”理解本用法。','neutral','published',1363);
