INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-te-oku','ja','te-oku','提前准备或保留状态','て形 + おく',3,'提前准备或保留状态','提前准备或保留状态','て形 + おく','为以后准备，也可保留某状态。','为以后准备，也可保留某状态。','为以后准备，也可保留某状态。','结合“先暂定为计划吧。”理解本用法。','neutral','published',1364);
