INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-te-kuru','ja','te-kuru','变化到现在','て形 + くる',4,'变化到现在','变化到现在','て形 + くる','本例说变化逐渐发展至现在；不是空间移动。','本例说变化逐渐发展至现在；不是空间移动。','本例说变化逐渐发展至现在；不是空间移动。','结合“渐渐喜欢上了。”理解本用法。','neutral','published',1365);
