INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-tari','ja','tari','列举动作或状态','た形 + り ... た形 + りする',3,'列举动作或状态','列举动作或状态','た形 + り ... た形 + りする','非穷尽列举；最后用する承担时态。','非穷尽列举；最后用する承担时态。','非穷尽列举；最后用する承担时态。','结合“疼痛时有时无。”理解本用法。','neutral','published',1366);
