INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-bakari','ja','bakari','刚做完','た形 + ばかり',3,'刚做完','刚做完','た形 + ばかり','说话人感到时间短，不一定刚刚发生。','说话人感到时间短，不一定刚刚发生。','说话人感到时间短，不一定刚刚发生。','结合“才刚开始。”理解本用法。','neutral','published',1367);
