INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-tokoro','ja','tokoro','刚好处于动作阶段','た形 + ところ',3,'刚好处于动作阶段','刚好处于动作阶段','た形 + ところ','本例表示刚完成；与辞书形、ている接续含义不同。','本例表示刚完成；与辞书形、ている接续含义不同。','本例表示刚完成；与辞书形、ている接续含义不同。','结合“我刚起床。”理解本用法。','neutral','published',1368);
