INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-youda','ja','youda','根据间接证据推断','普通形 + ようだ',4,'根据间接证据推断','根据间接证据推断','普通形 + ようだ','名词接の，な形容词接な；与样态そう接续不同。','名词接の，な形容词接な；与样态そう接续不同。','名词接の，な形容词接な；与样态そう接续不同。','结合“好像上了与订单不同的菜。”理解本用法。','neutral','published',1369);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-youda','ja-youda','ja','注文と違うものが来たようです。','好像上了与订单不同的菜。','名词接の，な形容词接な；与样态そう接续不同。','[{"text":"注文","reading":"ちゅうもん"},{"text":"と"},{"text":"違","reading":"ちが"},{"text":"うものが"},{"text":"来","reading":"き"},{"text":"たようです。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-hearsay-sou','ja','hearsay-sou','传闻','普通形 + そうだ',4,'传闻','传闻','普通形 + そうだ','转述所得信息；动词辞书形接そう，不用ます干。','转述所得信息；动词辞书形接そう，不用ます干。','转述所得信息；动词辞书形接そう，不用ます干。','结合“听说明天会下雨。”理解本用法。','neutral','published',1370);
