INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-ni-kakawarazu','ja','ni-kakawarazu','不论条件','名词 + にかかわらず',5,'不论条件','不论条件','名词 + にかかわらず','较正式，说明某因素不影响后项。','较正式，说明某因素不影响后项。','较正式，说明某因素不影响后项。','结合“不管预报如何，都该准备备用方案。”理解本用法。','formal','published',1371);
