INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-nakute-mo-ii','ja','nakute-mo-ii','没有必要','ない形去い + くてもいい',3,'没有必要','没有必要','ない形去い + くてもいい','表达不必，不是禁止；禁止常用てはいけない。','表达不必，不是禁止；禁止常用てはいけない。','表达不必，不是禁止；禁止常用てはいけない。','结合“不必勉强说。”理解本用法。','neutral','published',1373);
