INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-honorific','ja','honorific','尊敬对方行为','おっしゃる / なさる 等',4,'尊敬对方行为','尊敬对方行为','おっしゃる / なさる 等','提升对方行为主体，不用于抬高自己的动作。','提升对方行为主体，不用于抬高自己的动作。','提升对方行为主体，不用于抬高自己的动作。','结合“我理解您说的。”理解本用法。','neutral','published',1378);
