INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-humble','ja','humble','谦逊地描述自己行为','いたす / 伺う 等',4,'谦逊地描述自己行为','谦逊地描述自己行为','いたす / 伺う 等','降低己方行为以表示对对方的尊重；不是贬低自身价值。','降低己方行为以表示对对方的尊重；不是贬低自身价值。','降低己方行为以表示对对方的尊重；不是贬低自身价值。','结合“我来确认。”理解本用法。','neutral','published',1379);
