INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-tohaie','ja','tohaie','承认后转折','とはいえ + clause',5,'承认后转折','承认后转折','とはいえ + clause','承接已承认事实再补充限制；不能用于毫无关联的新话题。','承接已承认事实再补充限制；不能用于毫无关联的新话题。','承接已承认事实再补充限制；不能用于毫无关联的新话题。','结合“很贵。不过很方便。”理解本用法。','formal','published',1380);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-tohaie','ja-tohaie','ja','高いです。とはいえ、便利です。','很贵。不过很方便。','承接已承认事实再补充限制；不能用于毫无关联的新话题。','[{"text":"高","reading":"たか"},{"text":"いです。とはいえ、"},{"text":"便利","reading":"べんり"},{"text":"です。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-wari-ni','ja','wari-ni','相较标准出乎意料','名词 + の割に',4,'相较标准出乎意料','相较标准出乎意料','名词 + の割に','比较实际与标准预期；名词后需要の。','比较实际与标准预期；名词后需要の。','比较实际与标准预期；名词后需要の。','结合“就价格而言很不错。”理解本用法。','neutral','published',1381);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-wari-ni','ja-wari-ni','ja','値段の割にいいです。','就价格而言很不错。','比较实际与标准预期；名词后需要の。','[{"text":"値段","reading":"ねだん"},{"text":"の"},{"text":"割","reading":"わり"},{"text":"にいいです。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-kai','ja','kai','付出有所回报','た形 + 甲斐がある',5,'付出有所回报','付出有所回报','た形 + 甲斐がある','评价付出值得，不只表示动作完成。','评价付出值得，不只表示动作完成。','评价付出值得，不只表示动作完成。','结合“去得很值得。”理解本用法。','formal','published',1382);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-kai','ja-kai','ja','行った甲斐がありました。','去得很值得。','评价付出值得，不只表示动作完成。','[{"text":"行","reading":"い"},{"text":"った"},{"text":"甲斐","reading":"かい"},{"text":"がありました。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-zaru-wo-enai','ja','zaru-wo-enai','不得不采取','ない干 + ざるを得ない',6,'不得不采取','不得不采取','ない干 + ざるを得ない','正式表达别无选择；する变せざるを得ない。','正式表达别无选择；する变せざるを得ない。','正式表达别无选择；する变せざるを得ない。','结合“不得不更改计划。”理解本用法。','formal','published',1383);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-zaru-wo-enai','ja-zaru-wo-enai','ja','予定を変更せざるを得ません。','不得不更改计划。','正式表达别无选择；する变せざるを得ない。','[{"text":"予定","reading":"よてい"},{"text":"を"},{"text":"変更","reading":"へんこう"},{"text":"せざるを"},{"text":"得","reading":"え"},{"text":"ません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-ni-suginai','ja','ni-suginai','仅限于此','名词 + にすぎない',6,'仅限于此','仅限于此','名词 + にすぎない','限定或弱化评价；可能带有贬低语气。','限定或弱化评价；可能带有贬低语气。','限定或弱化评价；可能带有贬低语气。','结合“这只不过是一个例子。”理解本用法。','formal','published',1384);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-ni-suginai','ja-ni-suginai','ja','これは一つの例にすぎません。','这只不过是一个例子。','限定或弱化评价；可能带有贬低语气。','[{"text":"これは"},{"text":"一","reading":"ひと"},{"text":"つの"},{"text":"例","reading":"れい"},{"text":"にすぎません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-to-wa-kagiranai','ja','to-wa-kagiranai','不一定','普通形 + とは限らない',5,'不一定','不一定','普通形 + とは限らない','否定普遍成立，不等于反面一定成立。','否定普遍成立，不等于反面一定成立。','否定普遍成立，不等于反面一定成立。','结合“贵的不一定好。”理解本用法。','formal','published',1385);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-to-wa-kagiranai','ja-to-wa-kagiranai','ja','高ければいいとは限りません。','贵的不一定好。','否定普遍成立，不等于反面一定成立。','[{"text":"高","reading":"たか"},{"text":"ければいいとは"},{"text":"限","reading":"かぎ"},{"text":"りません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-wo-fumaete','ja','wo-fumaete','依据背景考虑','名词 + を踏まえて',6,'依据背景考虑','依据背景考虑','名词 + を踏まえて','正式讨论中以前项为判断基础，不表示逐字照办。','正式讨论中以前项为判断基础，不表示逐字照办。','正式讨论中以前项为判断基础，不表示逐字照办。','结合“根据结果重新审视计划。”理解本用法。','formal','published',1386);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-wo-fumaete','ja-wo-fumaete','ja','結果を踏まえて、計画を見直します。','根据结果重新审视计划。','正式讨论中以前项为判断基础，不表示逐字照办。','[{"text":"結果","reading":"けっか"},{"text":"を"},{"text":"踏","reading":"ふ"},{"text":"まえて、"},{"text":"計画","reading":"けいかく"},{"text":"を"},{"text":"見直","reading":"みなお"},{"text":"します。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-kanenai','ja','kanenai','有发生坏结果的可能','ます干 + かねない',6,'有发生坏结果的可能','有发生坏结果的可能','ます干 + かねない','多用于担心的不利后果，不能作为一般可能性的万能形式。','多用于担心的不利后果，不能作为一般可能性的万能形式。','多用于担心的不利后果，不能作为一般可能性的万能形式。','结合“可能招致误解。”理解本用法。','formal','published',1387);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-kanenai','ja-kanenai','ja','誤解を招きかねません。','可能招致误解。','多用于担心的不利后果，不能作为一般可能性的万能形式。','[{"text":"誤解","reading":"ごかい"},{"text":"を"},{"text":"招","reading":"まね"},{"text":"きかねません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-mono-no','ja','mono-no','承认事实但结果不同','普通形 + ものの',5,'承认事实但结果不同','承认事实但结果不同','普通形 + ものの','书面语让步；承认前项，却未出现预期后项。','书面语让步；承认前项，却未出现预期后项。','书面语让步；承认前项，却未出现预期后项。','结合“虽然买了，但还没用。”理解本用法。','formal','published',1388);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-mono-no','ja-mono-no','ja','買ったものの、まだ使っていません。','虽然买了，但还没用。','书面语让步；承认前项，却未出现预期后项。','[{"text":"買","reading":"か"},{"text":"ったものの、まだ"},{"text":"使","reading":"つか"},{"text":"っていません。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-beki','ja','beki','应当履行的判断','辞书形 + べきだ',5,'应当履行的判断','应当履行的判断','辞书形 + べきだ','规范性较强，不能轻率用于所有建议；する也可用すべき。','规范性较强，不能轻率用于所有建议；する也可用すべき。','规范性较强，不能轻率用于所有建议；する也可用すべき。','结合“应该确认条件。”理解本用法。','formal','published',1389);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-beki','ja-beki','ja','条件を確認すべきです。','应该确认条件。','规范性较强，不能轻率用于所有建议；する也可用すべき。','[{"text":"条件","reading":"じょうけん"},{"text":"を"},{"text":"確認","reading":"かくにん"},{"text":"すべきです。"}]');
INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-ni-hoka-naranai','ja','ni-hoka-naranai','强调本质判断','名词 + にほかならない',6,'强调本质判断','强调本质判断','名词 + にほかならない','正式而强烈的断定；证据不足时应避免过强结论。','正式而强烈的断定；证据不足时应避免过强结论。','正式而强烈的断定；证据不足时应避免过强结论。','结合“这正是努力的结果。”理解本用法。','formal','published',1390);
INSERT INTO v2_grammar_examples (id,grammar_id,language,text,translation_zh,explanation_zh,readings_json) VALUES ('c-ge-ja-ni-hoka-naranai','ja-ni-hoka-naranai','ja','これは努力の結果にほかなりません。','这正是努力的结果。','正式而强烈的断定；证据不足时应避免过强结论。','[{"text":"これは"},{"text":"努力","reading":"どりょく"},{"text":"の"},{"text":"結果","reading":"けっか"},{"text":"にほかなりません。"}]');
