INSERT INTO v2_grammar_points (id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,usage_zh,register,publication_state,sort_order) VALUES ('ja-request-onegai','ja','request-onegai','提出所需内容','名词 + を / でお願いします',2,'提出所需内容','提出所需内容','名词 + を / でお願いします','を标记所求内容；で可以表示选择的方式。','を标记所求内容；で可以表示选择的方式。','を标记所求内容；で可以表示选择的方式。','结合“请给我水。”理解本用法。','neutral','published',1392);
