INSERT INTO v2_editorial_decisions (concept_id,source_sha256,source_json,prior_review_flag,status,decision_zh,reviewer_type,revision,reviewed_at) VALUES (27,'aa361af8defda4b94c26cf750859e9610e3580ba8cc5b103dc825daacf428996','{"concept":{"id":27,"slug":"concept-27","topic_id":"chat","zh":"澄清一句话听起来比本意更强硬","sort_order":27,"published":1,"concept_type":"dialogue","usage_note":"harsh 指语气刺耳；きつい也可形容说法严厉。回应先承认效果，再改说法，避免只辩解本意。"},"expressions":[{"id":53,"concept_id":27,"language":"en","text":"A: That sounded a bit harsh.\nB: You''re right. Let me rephrase that.","ipa":"/eɪ ðæt ˈsaʊndɪd ə bɪt hɑrʃ\nbi jʊr raɪt lɛt mi ˌriˈfreɪz ðæt/","hiragana":null,"difficulty":6,"register":"见对话说明（朋友／同事／服务场景）","sort_order":0,"is_primary":1,"grammar_point_id":53,"metadata_json":"{\"usage\":\"harsh 指语气刺耳；きつい也可形容说法严厉。回应先承认效果，再改说法，避免只辩解本意。\",\"example\":\"A: That sounded a bit harsh.\\nB: You''re right. Let me rephrase that.\",\"turns\":[{\"speaker\":\"A\",\"text\":\"That sounded a bit harsh.\"},{\"speaker\":\"B\",\"text\":\"You''re right. Let me rephrase that.\"}]}"},{"id":54,"concept_id":27,"language":"ja","text":"A: ちょっときつく聞こえたよ。\nB: そうだね。言い直すね。","ipa":null,"hiragana":"A: ちょっときつくきこえたよ。\nB: そうだね。いいなおすね。","difficulty":6,"register":"见对话说明（朋友／同事／服务场景）","sort_order":0,"is_primary":1,"grammar_point_id":54,"metadata_json":"{\"usage\":\"harsh 指语气刺耳；きつい也可形容说法严厉。回应先承认效果，再改说法，避免只辩解本意。\",\"example\":\"A: ちょっときつく聞こえたよ。\\nB: そうだね。言い直すね。\",\"turns\":[{\"speaker\":\"A\",\"text\":\"ちょっときつく聞こえたよ。\",\"reading\":\"ちょっときつくきこえたよ。\",\"readings\":[{\"text\":\"ちょっときつく\"},{\"text\":\"聞\",\"reading\":\"き\"},{\"text\":\"こえたよ。\"}]},{\"speaker\":\"B\",\"text\":\"そうだね。言い直すね。\",\"reading\":\"そうだね。いいなおすね。\",\"readings\":[{\"text\":\"そうだね。\"},{\"text\":\"言\",\"reading\":\"い\"},{\"text\":\"い\"},{\"text\":\"直\",\"reading\":\"なお\"},{\"text\":\"すね。\"}]}]}"}]}',0,'resolved','harsh 指语气刺耳；きつい也可形容说法严厉。回应先承认效果，再改说法，避免只辩解本意。','model_assisted','35c-editorial-1','2026-09-09T00:00:00Z');
