INSERT INTO v2_editorial_decisions (concept_id,source_sha256,source_json,prior_review_flag,status,decision_zh,reviewer_type,revision,reviewed_at) VALUES (177,'123c6a80310b80c55dd24e430b662a7b6a8dbd437ae962d0caa11457dac55b13','{"concept":{"id":177,"slug":"concept-177","topic_id":"plans","zh":"聊计划改变后的安排","sort_order":177,"published":1,"concept_type":"dialogue","usage_note":"instead 表示选择替代方案；ことにした说明自己作出的决定，区别于外部决定的ことになった。"},"expressions":[{"id":353,"concept_id":177,"language":"en","text":"A: Are you still going away this weekend?\nB: No, we decided to stay home instead.","ipa":"/eɪ ɑr ju stɪl ˈɡoʊɪŋ əˈweɪ ðɪs ˈwiːkɛnd\nbi noʊ wi dɪˈsaɪdɪd tə steɪ hoʊm ɪnˈstɛd/","hiragana":null,"difficulty":3,"register":"见对话说明（朋友／同事／服务场景）","sort_order":0,"is_primary":1,"grammar_point_id":353,"metadata_json":"{\"usage\":\"instead 表示选择替代方案；ことにした说明自己作出的决定，区别于外部决定的ことになった。\",\"example\":\"A: Are you still going away this weekend?\\nB: No, we decided to stay home instead.\",\"turns\":[{\"speaker\":\"A\",\"text\":\"Are you still going away this weekend?\"},{\"speaker\":\"B\",\"text\":\"No, we decided to stay home instead.\"}]}"},{"id":354,"concept_id":177,"language":"ja","text":"A: 週末は出かける予定のまま？\nB: ううん、代わりに家で過ごすことにした。","ipa":null,"hiragana":"A: しゅうまつはでかけるよていのまま？\nB: ううん、かわりにいえですごすことにした。","difficulty":4,"register":"见对话说明（朋友／同事／服务场景）","sort_order":0,"is_primary":1,"grammar_point_id":354,"metadata_json":"{\"usage\":\"instead 表示选择替代方案；ことにした说明自己作出的决定，区别于外部决定的ことになった。\",\"example\":\"A: 週末は出かける予定のまま？\\nB: ううん、代わりに家で過ごすことにした。\",\"turns\":[{\"speaker\":\"A\",\"text\":\"週末は出かける予定のまま？\",\"reading\":\"しゅうまつはでかけるよていのまま？\",\"readings\":[{\"text\":\"週末\",\"reading\":\"しゅうまつ\"},{\"text\":\"は\"},{\"text\":\"出\",\"reading\":\"で\"},{\"text\":\"かける\"},{\"text\":\"予定\",\"reading\":\"よてい\"},{\"text\":\"のまま？\"}]},{\"speaker\":\"B\",\"text\":\"ううん、代わりに家で過ごすことにした。\",\"reading\":\"ううん、かわりにいえですごすことにした。\",\"readings\":[{\"text\":\"ううん、\"},{\"text\":\"代\",\"reading\":\"か\"},{\"text\":\"わりに\"},{\"text\":\"家\",\"reading\":\"いえ\"},{\"text\":\"で\"},{\"text\":\"過\",\"reading\":\"す\"},{\"text\":\"ごすことにした。\"}]}]}"}]}',0,'resolved','instead 表示选择替代方案；ことにした说明自己作出的决定，区别于外部决定的ことになった。','model_assisted','35c-editorial-1','2026-09-09T00:00:00Z');
