INSERT INTO v2_editorial_decisions (concept_id,source_sha256,source_json,prior_review_flag,status,decision_zh,reviewer_type,revision,reviewed_at) VALUES (180,'b4b9a89e2f62685513709c8080fe24ef0250cf8191ec6ff8189f8282d9ad52dc','{"concept":{"id":180,"slug":"concept-180","topic_id":"plans","zh":"表达本来会做某事但被另一件事打断","sort_order":180,"published":1,"concept_type":"pattern","usage_note":"例：I would have joined you, but I had to work.／参加するつもりでしたが、仕事が入ってしまいました。英语反事实结构比日语意图表达更明确，不是所有场景可互换。"},"expressions":[{"id":359,"concept_id":180,"language":"en","text":"I would have ..., but ...","ipa":"/aɪ wʊd hæv bət/","hiragana":null,"difficulty":5,"register":"日常；具体语气见用法","sort_order":0,"is_primary":1,"grammar_point_id":359,"metadata_json":"{\"usage\":\"例：I would have joined you, but I had to work.／参加するつもりでしたが、仕事が入ってしまいました。英语反事实结构比日语意图表达更明确，不是所有场景可互换。\",\"example\":\"I would have joined you, but I had to work.\",\"structure\":\"I would have ..., but ...\"}"},{"id":360,"concept_id":180,"language":"ja","text":"〜つもりでしたが、〜。","ipa":null,"hiragana":"〜つもりでしたが、〜。","difficulty":5,"register":"日常；具体语气见用法","sort_order":0,"is_primary":1,"grammar_point_id":360,"metadata_json":"{\"usage\":\"例：I would have joined you, but I had to work.／参加するつもりでしたが、仕事が入ってしまいました。英语反事实结构比日语意图表达更明确，不是所有场景可互换。\",\"example\":\"参加するつもりでしたが、仕事が入ってしまいました\",\"structure\":\"〜つもりでしたが、〜。\"}"}]}',1,'resolved','补全被工作打断的参加语境；英语表达未实现结果，日语表达原有意图，不宣称结构等价。 例：I would have joined you, but I had to work.／参加するつもりでしたが、仕事が入ってしまいました。英语反事实结构比日语意图表达更明确，不是所有场景可互换。','model_assisted','35c-editorial-1','2026-09-09T00:00:00Z');
