INSERT INTO v2_editorial_decisions (concept_id,source_sha256,source_json,prior_review_flag,status,decision_zh,reviewer_type,revision,reviewed_at) VALUES (183,'873e3540e101ca0cc5d765e6dc10898ade913fac2bd82072c20b304398f440ab','{"concept":{"id":183,"slug":"concept-183","topic_id":"plans","zh":"回顾一次不顺利但有收获的经历","sort_order":183,"published":1,"concept_type":"dialogue","usage_note":"worth it 指投入值得；甲斐がある强调付出有意义。肯定收获不意味着否定经历中的失望。"},"expressions":[{"id":365,"concept_id":183,"language":"en","text":"A: Was the trip worth it after all?\nB: It wasn''t what I''d hoped for, but I learned a lot.","ipa":"/eɪ wəz ðə trɪp wɜrθ ɪt ˈæftər ɔl\nbi ɪt ˈwɑzənt wʌt aɪd hoʊpt fər bət aɪ lɜrnd ə lɑt/","hiragana":null,"difficulty":6,"register":"见对话说明（朋友／同事／服务场景）","sort_order":0,"is_primary":1,"grammar_point_id":365,"metadata_json":"{\"usage\":\"worth it 指投入值得；甲斐がある强调付出有意义。肯定收获不意味着否定经历中的失望。\",\"example\":\"A: Was the trip worth it after all?\\nB: It wasn''t what I''d hoped for, but I learned a lot.\",\"turns\":[{\"speaker\":\"A\",\"text\":\"Was the trip worth it after all?\"},{\"speaker\":\"B\",\"text\":\"It wasn''t what I''d hoped for, but I learned a lot.\"}]}"},{"id":366,"concept_id":183,"language":"ja","text":"A: 結局、行った甲斐はあった？\nB: 期待どおりではなかったけど、学ぶことは多かったよ。","ipa":null,"hiragana":"A: けっきょく、いったかいはあった？\nB: きたいどおりではなかったけど、まなぶことはおおかったよ。","difficulty":6,"register":"见对话说明（朋友／同事／服务场景）","sort_order":0,"is_primary":1,"grammar_point_id":366,"metadata_json":"{\"usage\":\"worth it 指投入值得；甲斐がある强调付出有意义。肯定收获不意味着否定经历中的失望。\",\"example\":\"A: 結局、行った甲斐はあった？\\nB: 期待どおりではなかったけど、学ぶことは多かったよ。\",\"turns\":[{\"speaker\":\"A\",\"text\":\"結局、行った甲斐はあった？\",\"reading\":\"けっきょく、いったかいはあった？\",\"readings\":[{\"text\":\"結局\",\"reading\":\"けっきょく\"},{\"text\":\"、\"},{\"text\":\"行\",\"reading\":\"い\"},{\"text\":\"った\"},{\"text\":\"甲斐\",\"reading\":\"かい\"},{\"text\":\"はあった？\"}]},{\"speaker\":\"B\",\"text\":\"期待どおりではなかったけど、学ぶことは多かったよ。\",\"reading\":\"きたいどおりではなかったけど、まなぶことはおおかったよ。\",\"readings\":[{\"text\":\"期待\",\"reading\":\"きたい\"},{\"text\":\"どおりではなかったけど、\"},{\"text\":\"学\",\"reading\":\"まな\"},{\"text\":\"ぶことは\"},{\"text\":\"多\",\"reading\":\"おお\"},{\"text\":\"かったよ。\"}]}]}"}]}',0,'resolved','worth it 指投入值得；甲斐がある强调付出有意义。肯定收获不意味着否定经历中的失望。','model_assisted','35c-editorial-1','2026-09-09T00:00:00Z');
